insert into questions (id, activity_id, position, type, prompt, data) values ('u01-l3-q01', 'u01-l3', 1, 'mcq', 'There is a sealed box with holes in the lid. You cannot open it. Which senses can you SAFELY use to guess what is inside?', '{"options":[{"id":"a","text":"Taste only"},{"id":"b","text":"Smell and hearing (shake it gently)"},{"id":"c","text":"No senses at all"}],"visual":{"kind":"emoji","value":"📦"}}'::jsonb) on conflict (id) do update set activity_id = excluded.activity_id, position = excluded.position, type = excluded.type, prompt = excluded.prompt, data = excluded.data;
